// Ecowitt WS90 via Shelly BLE Cloud Relay.
// Configure this MAC for your WS90:
const WS90_MAC = "aa:bb:cc:dd:ee:ff".toLowerCase();

function u16le(b, i) {
    return b[i] | (b[i + 1] << 8);
}
function s16le(b, i) {
    let v = u16le(b, i);
    return v & 0x8000 ? v - 0x10000 : v;
}
function u24le(b, i) {
    return b[i] | (b[i + 1] << 8) | (b[i + 2] << 16);
}

function decodeBTHome(base64) {
    const b = Buffer.from(base64, "base64");
    if (!b || b.length < 2) return {};

    // BTHome v2 device-info byte. WS90 uses unencrypted advertisements.
    let i = 1;
    const out = {};
    let speedCount = 0;

    while (i < b.length) {
        const id = b[i++];
        switch (id) {
            case 0x00: // packet id
                if (i + 1 > b.length) return out;
                out.packet_id = b[i++];
                break;
            case 0x01: // battery %
                if (i + 1 > b.length) return out;
                out.battery = b[i++];
                break;
            case 0x04: // pressure, 0.01 hPa
                if (i + 3 > b.length) return out;
                out.pressure = u24le(b, i) * 0.01; i += 3;
                break;
            case 0x05: // illuminance, 0.01 lux
                if (i + 3 > b.length) return out;
                out.illuminance = u24le(b, i) * 0.01; i += 3;
                break;
            case 0x08: // dew point, 0.01 C
                if (i + 2 > b.length) return out;
                out.dew_point = s16le(b, i) * 0.01; i += 2;
                break;
            case 0x0c: // capacitor voltage, 0.001 V
                if (i + 2 > b.length) return out;
                out.capacitor_voltage = u16le(b, i) * 0.001; i += 2;
                break;
            case 0x20: // rain binary state
                if (i + 1 > b.length) return out;
                out.rain = b[i++] !== 0;
                break;
            case 0x2e: // relative humidity, 1 %
                if (i + 1 > b.length) return out;
                out.humidity = b[i++];
                break;
            case 0x3a: // button/event byte
                if (i + 1 > b.length) return out;
                out.button = b[i++];
                break;
            case 0x44: { // speed, 0.01 m/s; WS90 sends wind then gust
                if (i + 2 > b.length) return out;
                const v = u16le(b, i) * 0.01; i += 2;
                if (speedCount++ === 0) out.wind_speed = v;
                else out.wind_gust = v;
                break;
            }
            case 0x45: // temperature, 0.1 C
                if (i + 2 > b.length) return out;
                out.temperature = s16le(b, i) * 0.1; i += 2;
                break;
            case 0x46: // UV index, 0.1
                if (i + 1 > b.length) return out;
                out.uv_index = b[i++] * 0.1;
                break;
            case 0x5e: // wind direction, 0.01 degrees
                if (i + 2 > b.length) return out;
                out.wind_direction = u16le(b, i) * 0.01; i += 2;
                break;
            case 0x5f: // precipitation, 0.1 mm
                if (i + 2 > b.length) return out;
                out.precipitation = u16le(b, i) * 0.1; i += 2;
                break;
            default:
                // Unknown BTHome object length cannot be inferred safely.
                // Stop this packet but preserve all already decoded fields.
                return out;
        }
    }
    return out;
}

const body = msg.payload && msg.payload.params ? msg.payload.params : msg.payload;
const devices = body && body.devices ? body.devices : {};
let ws = null;

Object.keys(devices).some(function(mac) {
    if (String(mac).toLowerCase() === WS90_MAC) {
        ws = devices[mac];
        return true;
    }
    return false;
});

if (!ws || !ws.sdata || !ws.sdata.fcd2) return null;

const candidate = {
    source: msg.ws90_gateway || "unknown",
    last_seen: Number(ws.last_seen || 0),
    sdata: ws.sdata.fcd2
};

flow.set("ws90_candidate_" + candidate.source, candidate);

const a = flow.get("ws90_candidate_shelly-a");
const b = flow.get("ws90_candidate_shelly-b");
const candidates = [a, b].filter(Boolean);
if (!candidates.length) return null;

candidates.sort(function(x, y) { return y.last_seen - x.last_seen; });
const freshest = candidates[0];

const fingerprint = freshest.last_seen + ":" + freshest.sdata;
if (flow.get("ws90_last_fingerprint") === fingerprint) return null;
flow.set("ws90_last_fingerprint", fingerprint);

const decoded = decodeBTHome(freshest.sdata);
const state = flow.get("ws90_state") || {};

Object.keys(decoded).forEach(function(k) {
    state[k] = decoded[k];
});

state.source = freshest.source;
state.last_seen = freshest.last_seen;
state.updated_at = Date.now();
flow.set("ws90_state", state);

msg.payload = state;
return msg;

const s = msg.payload || {};

function put(obj, key, value) {
    if (value !== undefined && value !== null && Number.isFinite(Number(value))) {
        obj[key] = Number(value);
    }
}

// Victron virtual Temperature device exposes temperature, humidity and pressure.
const temp = {};
put(temp, "Temperature", s.temperature);
put(temp, "Humidity", s.humidity);
put(temp, "Pressure", s.pressure);

// Victron virtual Meteo device natively exposes wind speed/direction.
// Do not map WS90 illuminance (lux) to Victron Irradiance (W/m2).
const meteo = {};
put(meteo, "WindSpeed", s.wind_speed);
if (s.wind_direction !== undefined && s.wind_direction !== null) {
    meteo.WindDirection = Math.round(Number(s.wind_direction));
}

const debug = {
    payload: s,
    topic: "ws90/state"
};

return [
    Object.keys(temp).length ? { payload: temp } : null,
    Object.keys(meteo).length ? { payload: meteo } : null,
    debug
];
